*{box-sizing:border-box}
html,body{margin:0;background:#132230;color:#e7eef4;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:13px}
button{font:inherit;color:inherit;cursor:pointer}
.num{font-variant-numeric:tabular-nums}
.wrap{display:flex;flex-direction:column;height:100vh}
.mh{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid #1f3346;flex:none}
.mh b{flex:1;font-size:15px}
.x{background:none;border:none;font-size:20px;color:#8ea3b5;line-height:1}
.mb{overflow:auto;padding:12px 16px 16px;display:flex;flex-direction:column;gap:12px;flex:1}
.note{font-size:12px;color:#e6d27a;background:#2a2f14;border:1px solid #5a5220;border-radius:6px;padding:7px 10px}
.grp{background:#0f1d29;border:1px solid #243a50;border-left:3px solid #fab219;border-radius:8px;padding:12px 14px}
.grp.sev-c{border-left-color:#d03b3b}.grp.sev-s{border-left-color:#ec835a}.grp.sev-w{border-left-color:#fab219}
.grp.st-ack,.grp.st-res{border-left-color:#4a5d70}.grp.st-flag{border-left-color:#9085e9}
.gh{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.gh b{font-size:14px}
.chip{font-size:11px;padding:1px 7px;border-radius:4px;background:#1a2733;border:1px solid #2a4258;color:#b9c9d6}
.chip .g{color:#8ea3b5;margin-right:3px}
.chip.st-open{color:#e7eef4}.chip.st-ack{color:#8ea3b5}
.chip.st-flag{border-color:#9085e9;color:#e7eef4;background:#221f3d}
.chip.st-res{border-color:#0ca30c;color:#e7eef4;background:#0f2a1a}
.sev{display:inline-flex;align-items:center;gap:5px;font-size:12px;color:#c9d6e0}
.sev i{width:8px;height:8px;border-radius:50%;display:inline-block}
.kv{display:grid;grid-template-columns:170px 1fr;gap:4px 12px;margin:10px 0;font-size:13px}
.kv span:nth-child(odd){color:#8ea3b5}
.msgs{font-size:12px;color:#c9d6e0;margin:6px 0;padding-left:18px}
.hist{font-size:12px;color:#8ea3b5;margin:4px 0 0;padding-left:18px}
.acts{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px}
.spacer{flex:1}
.btn{border:1px solid #2a4258;background:#0d1822;border-radius:6px;padding:6px 14px;font-size:12px}
.btn.pri{background:#1f4a73;border-color:#3b82c4}
.btn.flag.pri{background:#2c2658;border-color:#9085e9}
.btn.link{border:none;background:none;color:#7cb8f0;padding:0;text-decoration:underline}
.flagform{margin-top:10px;display:flex;flex-direction:column;gap:8px}
.flagform label{font-size:12px;color:#8ea3b5;display:flex;align-items:center;gap:8px}
select,textarea{background:#0d1822;color:#e7eef4;border:1px solid #2a4258;border-radius:6px;padding:6px 8px;font:inherit}
textarea{width:100%;min-height:60px}
.empty{padding:30px;color:#8ea3b5;text-align:center}

