// Error detail for the page's modal. It shows what the explorer sent and
// sends every action back to the page; Acknowledge / Flag are held for this
// page load only and are not saved to UBM.
var SEV = {c:"#d03b3b", s:"#ec835a", w:"#fab219"};
var M = {}, lastModel = "", draft = null;
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];}); }
function sess(){ var x=M.session||{}; return {ack:x.ack||{},flag:x.flag||{},log:x.log||{},to:x.to||{}}; }
function statusOf(g){
  if(g.resolved) return "res";
  var ss=sess();
  if(g.ids.some(function(i){ return ss.flag[i]; })) return "flag";
  if(g.ids.every(function(i){ return ss.ack[i]; })) return "ack";
  return "open";
}
var CHIP = {open:["st-open","Open"],ack:["st-ack","Acknowledged"],flag:["st-flag","⚑ Flagged"],res:["st-res","✓ Resolved"]};
function opt(v,l){ return '<option value="'+esc(v)+'">'+esc(l)+'</option>'; }

function render(){
  var root=document.getElementById("root"); if(!root) return;
  var p=M.popup;
  if(!p||!p.groups){ root.innerHTML='<div class="wrap"><div class="mh"><b>Validation error</b><button class="x" id="close">×</button></div><div class="empty">Nothing selected.</div></div>'; bind(); return; }
  var ss=sess();
  var body=p.groups.map(function(g){
    var st=statusOf(g), todo=g.todo||"either";
    var acts;
    if(st==="res") acts='<span class="chip st-res">✓ Resolved in UBM</span>';
    else if(st==="ack") acts='<button class="btn pri" data-act="reopen" data-g="'+esc(g.key)+'">Re-flag</button>';
    else if(st==="flag") acts='<span class="chip st-flag">⚑ With '+esc(ss.to[g.key]||"operator")+'</span>';
    else acts='<button class="btn'+(todo==="accept"?" pri":"")+'" data-act="acknowledge" data-g="'+esc(g.key)+'">Acknowledge</button>'+
              '<button class="btn flag'+(todo==="escalate"?" pri":"")+'" data-act="flag" data-g="'+esc(g.key)+'">⚑ Flag to operator</button>';
    var def=g.assignee?"Current assignee ("+g.assignee+")":(p.csm?"Customer CSM ("+p.csm+")":"Customer's default operator");
    var form=draft===g.key?'<div class="flagform"><label>Assign to <select id="flagto">'+opt("",def)+(M.operators||[]).map(function(o){ return opt(o.id,(String(o.name||"").trim())||o.email); }).join("")+'</select></label>'+
      '<textarea id="flagnote" placeholder="Note for the operator (optional)"></textarea>'+
      '<div class="acts"><button class="btn flag pri" data-act="escalate" data-g="'+esc(g.key)+'">Send flag</button><button class="btn" data-act="cancel">Cancel</button></div></div>':'';
    var hist=[g.raised].concat(ss.log[g.key]||[]);
    return '<div class="grp '+(st==="open"?"sev-"+g.sevKey:"st-"+st)+'"><div class="gh"><b>'+esc(g.code)+' · '+esc(g.name)+'</b>'+
      '<span class="chip '+CHIP[st][0]+'">'+CHIP[st][1]+'</span><span class="chip"><span class="g">'+esc(g.glyph)+'</span>'+esc(g.place)+'</span>'+
      '<span class="sev"><i style="background:'+SEV[g.sevKey]+'"></i>Severity '+esc(g.sev)+'</span>'+
      (g.todo?'<span class="chip">Default: '+({accept:"Accept",escalate:"Escalate",either:"Either"}[g.todo])+'</span>':'')+'</div>'+
      '<div class="kv">'+g.kv.map(function(x){ return '<span>'+esc(x[0])+'</span><span class="num">'+esc(x[1])+'</span>'; }).join("")+'</div>'+
      (g.msgs.length?'<ul class="msgs">'+g.msgs.map(function(m){ return '<li>'+esc(m)+'</li>'; }).join("")+(g.moreMsgs?'<li>+'+g.moreMsgs+' more</li>':'')+'</ul>':'')+
      '<ul class="hist">'+hist.map(function(h){ return '<li>'+esc(h)+'</li>'; }).join("")+'</ul>'+
      '<div class="acts">'+acts+(g.billId?'<span class="spacer"></span><button class="btn link" data-open="'+esc(g.billId)+'">Open bill '+esc(g.billId)+'</button>':'')+'</div>'+form+'</div>';
  }).join("");
  root.innerHTML='<div class="wrap"><div class="mh"><b>'+esc(p.title)+'</b><button class="x" id="close" title="Close">×</button></div>'+
    '<div class="mb"><div class="note">Prototype: Acknowledge and Flag are kept for this page visit only and are not saved to UBM.</div>'+body+'</div></div>';
  bind();
}

function groupOf(key){ return ((M.popup||{}).groups||[]).filter(function(g){ return g.key===key; })[0]; }
function action(kind,key){
  if(kind==="flag"){ draft=key; render(); return; }
  if(kind==="cancel"){ draft=null; render(); return; }
  var g=groupOf(key); if(!g) return;
  var p={action:kind, groupKey:g.key, errorIds:g.ids, code:g.code, recordId:g.recordId, billId:g.billId,
         customerId:M.popup.customerId, locationId:M.popup.locationId, accounts:g.accounts};
  if(kind==="escalate"){
    var sel=document.getElementById("flagto"), n=(document.getElementById("flagnote")||{}).value||"";
    p.assigneeId=sel&&sel.value?Number(sel.value):null;
    p.assigneeName=sel?sel.options[sel.selectedIndex].text:"";
    p.note=n; draft=null;
  }
  appsmith.updateModel({errorAction:p});
  appsmith.triggerEvent("onErrorAction",{errorAction:p});
}
function bind(){
  var c=document.getElementById("close"); if(c) c.onclick=function(){ draft=null; appsmith.triggerEvent("onClose"); };
  document.getElementById("root").onclick=function(e){
    var t=e.target; if(!t.closest) return;
    var a=t.closest("[data-act]"); if(a){ action(a.getAttribute("data-act"),a.getAttribute("data-g")); return; }
    var o=t.closest("[data-open]"); if(o){ var id=o.getAttribute("data-open"); appsmith.updateModel({pickedBill:id}); appsmith.triggerEvent("onOpenBill",{pickedBill:id}); }
  };
}
function tick(){
  try{
    var m=(window.appsmith&&appsmith.model)||{}, s=JSON.stringify(m);
    // do not redraw under someone typing a flag note
    var typing=draft&&document.activeElement&&/^(TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    if(s!==lastModel&&!typing){
      if(M.popup&&m.popup&&JSON.stringify(M.popup.groups.map(function(g){return g.key;}))!==JSON.stringify(m.popup.groups.map(function(g){return g.key;}))) draft=null;
      lastModel=s; M=m; render();
    }
  }catch(e){}
}
tick(); setInterval(tick,300);

